## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/strokeLogic.ts`

```typescript
/**
 * Acute Ischemic Stroke Clinical Logic Engine
 * Based on: AHA/ASA 2026 Guideline for Early Management of Acute Ischemic Stroke
 * Reference: Stroke. 2026; Prabhakaran S, et al.
 * Key trials: DAWN (PMID:29129157), DEFUSE-3 (PMID:29129157), NINDS tPA (PMID:7477192)
 *
 * Disclaimer: For clinical decision support only. Does not replace clinical judgment.
 * Not affiliated with or endorsed by the American Heart Association or American Stroke Association.
 */

// ─── Input Types ───────────────────────────────────────────────────────────────

export type StrokeOnsetWindow =
  | "within_3h"
  | "3_to_4_5h"
  | "4_5_to_9h"
  | "9_to_24h"
  | "wake_up_unknown"
  | "beyond_24h";

export type VesselOcclusion =
  | "lvo_anterior"   // Large vessel occlusion — anterior circulation (ICA, M1, M2)
  | "lvo_posterior"  // Basilar artery occlusion
  | "small_vessel"   // Lacunar / small vessel
  | "no_occlusion"
  | "unknown";

export type ImagingAvailability =
  | "ct_only"
  | "ct_perfusion"
  | "mri_dwi"
  | "ct_and_perfusion"
  | "none";

export interface StrokeInput {
  // Timing
  onsetWindow: StrokeOnsetWindow;
  lastKnownWellMinutes: number; // minutes from last known well

  // Severity
  nihssScore: number; // 0-42
  isDisabling: boolean; // clinician judgment — symptoms disabling to patient

  // Vessel
  vesselOcclusion: VesselOcclusion;
  aspectsScore: number; // 0-10; ≥6 generally favorable for thrombectomy

  // Imaging
  imagingAvailability: ImagingAvailability;
  perfusionMismatchRatio: number; // Tmax>6s volume / core infarct volume; ≥1.8 favorable
  coreInfarctVolumeMl: number; // mL; <70 mL favorable for extended window

  // Patient factors
  ageYears: number;
  hasAnticoagulation: boolean;
  anticoagulantType: "warfarin" | "doac" | "heparin" | "none";
  inrIfWarfarin: number; // relevant if warfarin
  plateletCount: number; // ×10³/µL
  bloodGlucose: number; // mg/dL
  systolicBP: number; // mmHg
  hasRecentSurgery: boolean; // within 14 days
  hasRecentIntracranialSurgery: boolean; // within 3 months
  hasHistoryICH: boolean;
  hasActiveBleeding: boolean;
  hasEndocarditis: boolean;
  isPregnant: boolean;

  // Post-treatment context (for anticoagulation timing)
  isPostAcutePhase: boolean; // >24h from onset, asking about secondary prevention
  strokeMechanism: "cardioembolic" | "large_artery" | "small_vessel" | "cryptogenic" | "unknown";
  hasAtrialFibrillation: boolean;
  nihssAtPresentation: number; // for anticoagulation timing decision
}

// ─── Output Types ──────────────────────────────────────────────────────────────

export interface StrokeRecommendation {
  primaryRecommendation: string;
  ivThrombolysisEligibility: "eligible" | "ineligible" | "consider_with_caution";
  thrombectomyEligibility: "eligible" | "ineligible" | "consider_extended_window";
  ivThrombolysisRationale: string;
  thrombectomyRationale: string;
  anticoagulationTiming: string;
  urgentFlags: string[];
  treatmentPathway: string;
  nextSteps: string[];
  monitoringPlan: string[];
  evidenceLevel: string;
  rationale: string;
  references: Array<{ citation: string; pmid?: string }>;
}

// ─── Main Logic Function ───────────────────────────────────────────────────────

export function assessStroke(input: StrokeInput): StrokeRecommendation {
  const urgentFlags: string[] = [];
  const nextSteps: string[] = [];
  const monitoringPlan: string[] = [];

  // ─── Urgent Flags ───────────────────────────────────────────────────────────
  if (input.systolicBP > 185) {
    urgentFlags.push(
      `SBP ${input.systolicBP} mmHg — must lower to ≤185/110 mmHg before IV thrombolysis`
    );
  }
  if (input.bloodGlucose < 50 || input.bloodGlucose > 400) {
    urgentFlags.push(
      `Blood glucose ${input.bloodGlucose} mg/dL — correct hypoglycemia/severe hyperglycemia before thrombolysis`
    );
  }
  if (input.hasActiveBleeding) {
    urgentFlags.push("Active bleeding — IV thrombolysis and thrombectomy contraindicated");
  }
  if (input.vesselOcclusion === "lvo_posterior" && input.nihssScore >= 10) {
    urgentFlags.push(
      "Basilar artery occlusion with NIHSS ≥10 — high mortality without reperfusion; expedite thrombectomy evaluation"
    );
  }
  if (input.plateletCount < 100) {
    urgentFlags.push(`Platelet count ${input.plateletCount}×10³/µL — thrombolysis contraindicated if <100`);
  }

  // ─── IV Thrombolysis Eligibility ────────────────────────────────────────────
  let ivThrombolysisEligibility: StrokeRecommendation["ivThrombolysisEligibility"] = "ineligible";
  let ivThrombolysisRationale = "";

  const absoluteContraindications =
    input.hasActiveBleeding ||
    input.hasHistoryICH ||
    input.hasEndocarditis ||
    input.isPregnant ||
    input.hasRecentIntracranialSurgery ||
    input.plateletCount < 100 ||
    (input.hasAnticoagulation && input.anticoagulantType === "warfarin" && input.inrIfWarfarin > 1.7) ||
    (input.hasAnticoagulation && input.anticoagulantType === "doac");

  if (absoluteContraindications) {
    ivThrombolysisEligibility = "ineligible";
    ivThrombolysisRationale = "Absolute contraindication to IV thrombolysis present.";
    if (input.hasHistoryICH) ivThrombolysisRationale += " Prior ICH.";
    if (input.hasActiveBleeding) ivThrombolysisRationale += " Active bleeding.";
    if (input.anticoagulantType === "doac") ivThrombolysisRationale += " Recent DOAC use.";
    if (input.plateletCount < 100) ivThrombolysisRationale += ` Platelet count ${input.plateletCount}.`;
  } else if (
    (input.onsetWindow === "within_3h" || input.onsetWindow === "3_to_4_5h") &&
    input.isDisabling &&
    input.nihssScore >= 1
  ) {
    ivThrombolysisEligibility = "eligible";
    ivThrombolysisRationale =
      input.onsetWindow === "within_3h"
        ? "IV alteplase 0.9 mg/kg (max 90 mg) or tenecteplase 0.25 mg/kg (max 25 mg) within 3h — Class I recommendation (AHA/ASA 2026). Tenecteplase preferred if LVO present for logistical ease."
        : "IV thrombolysis within 4.5h — Class I for most patients. Exclude: age >80 with severe stroke + diabetes, prior stroke + diabetes, NIHSS >25, anticoagulation, large infarct on imaging.";
  } else if (
    (input.onsetWindow === "4_5_to_9h" || input.onsetWindow === "wake_up_unknown") &&
    (input.imagingAvailability === "ct_perfusion" || input.imagingAvailability === "mri_dwi") &&
    input.perfusionMismatchRatio >= 1.8 &&
    input.coreInfarctVolumeMl < 70
  ) {
    ivThrombolysisEligibility = "eligible";
    ivThrombolysisRationale =
      "Extended window thrombolysis (4.5-9h or wake-up stroke) — eligible based on perfusion imaging mismatch (EXTEND trial criteria: mismatch ratio ≥1.8, core <70 mL). AHA/ASA 2026 Class IIa.";
  } else if (input.onsetWindow === "within_3h" && !input.isDisabling) {
    ivThrombolysisEligibility = "consider_with_caution";
    ivThrombolysisRationale =
      "Non-disabling symptoms within 3h — shared decision-making. Thrombolysis may be considered but benefit uncertain for minor strokes (NIHSS 0-5 without disabling features).";
  } else {
    ivThrombolysisEligibility = "ineligible";
    ivThrombolysisRationale =
      "Outside thrombolysis window or insufficient perfusion imaging evidence for extended window therapy.";
  }

  // ─── Thrombectomy Eligibility ────────────────────────────────────────────────
  let thrombectomyEligibility: StrokeRecommendation["thrombectomyEligibility"] = "ineligible";
  let thrombectomyRationale = "";

  if (input.vesselOcclusion === "lvo_anterior") {
    if (
      (input.onsetWindow === "within_3h" || input.onsetWindow === "3_to_4_5h") &&
      input.nihssScore >= 6 &&
      input.aspectsScore >= 6
    ) {
      thrombectomyEligibility = "eligible";
      thrombectomyRationale =
        "LVO anterior circulation with NIHSS ≥6 and ASPECTS ≥6 within 6h — Class I thrombectomy indication (AHA/ASA 2026). Proceed immediately.";
    } else if (
      (input.onsetWindow === "4_5_to_9h" || input.onsetWindow === "9_to_24h" || input.onsetWindow === "wake_up_unknown") &&
      input.nihssScore >= 6 &&
      input.ageYears < 80 &&
      input.aspectsScore >= 3
    ) {
      thrombectomyEligibility = "consider_extended_window";
      thrombectomyRationale =
        "Extended window thrombectomy (6-24h) — eligible if DAWN criteria (age/NIHSS/infarct volume mismatch) or DEFUSE-3 criteria (perfusion mismatch ratio ≥1.8, core <70 mL) met. AHA/ASA 2026 Class I for 6-16h, Class IIa for 16-24h.";
    } else if (input.aspectsScore >= 3 && input.aspectsScore <= 5 && input.nihssScore >= 6) {
      thrombectomyEligibility = "consider_extended_window";
      thrombectomyRationale =
        "Low ASPECTS (3-5) — thrombectomy may still be considered if age <80, NIHSS ≥6, and no significant mass effect (AHA/ASA 2026 Class IIb). Discuss with neurointerventional team.";
    } else {
      thrombectomyEligibility = "ineligible";
      thrombectomyRationale = "Does not meet standard thrombectomy criteria — NIHSS <6, ASPECTS <3, or outside window without perfusion mismatch.";
    }
  } else if (input.vesselOcclusion === "lvo_posterior") {
    if (input.nihssScore >= 10 && input.onsetWindow !== "beyond_24h") {
      thrombectomyEligibility = "eligible";
      thrombectomyRationale =
        "Basilar artery occlusion with NIHSS ≥10 and onset <24h — thrombectomy recommended (AHA/ASA 2026 Class I based on BASICS and ATTENTION trials). High mortality without reperfusion.";
    } else {
      thrombectomyEligibility = "consider_extended_window";
      thrombectomyRationale =
        "Basilar artery occlusion with NIHSS <10 — consider thrombectomy based on clinical trajectory and imaging. Discuss with neurointerventional team.";
    }
  } else {
    thrombectomyEligibility = "ineligible";
    thrombectomyRationale =
      input.vesselOcclusion === "small_vessel"
        ? "Small vessel / lacunar stroke — thrombectomy not indicated. IV thrombolysis if eligible."
        : "No confirmed LVO — thrombectomy not indicated without vessel imaging confirmation.";
  }

  // ─── Anticoagulation Timing ──────────────────────────────────────────────────
  let anticoagulationTiming = "";
  if (input.isPostAcutePhase && input.hasAtrialFibrillation) {
    if (input.nihssAtPresentation <= 8) {
      anticoagulationTiming =
        "Cardioembolic stroke (AF) with mild deficit (NIHSS ≤8) — initiate anticoagulation at 48-72h after onset if no hemorrhagic transformation on repeat imaging (AHA/ASA 2026 Class IIa).";
    } else if (input.nihssAtPresentation <= 15) {
      anticoagulationTiming =
        "Moderate stroke (NIHSS 9-15) with AF — initiate anticoagulation at 5-7 days if no hemorrhagic transformation. Repeat CT/MRI before starting.";
    } else {
      anticoagulationTiming =
        "Severe stroke (NIHSS >15) with AF — delay anticoagulation 14 days. High risk of hemorrhagic transformation. Aspirin in interim.";
    }
  } else if (input.isPostAcutePhase && input.strokeMechanism === "large_artery") {
    anticoagulationTiming =
      "Large artery atherosclerosis — dual antiplatelet therapy (aspirin + clopidogrel) for 21 days, then single antiplatelet. Anticoagulation not indicated unless AF identified.";
  } else if (input.isPostAcutePhase && input.strokeMechanism === "small_vessel") {
    anticoagulationTiming =
      "Small vessel / lacunar stroke — single antiplatelet therapy (aspirin or clopidogrel). Anticoagulation not indicated.";
  } else {
    anticoagulationTiming =
      "Anticoagulation timing depends on stroke mechanism, severity, and hemorrhagic transformation risk. Reassess at 24-48h with repeat imaging.";
  }

  // ─── Treatment Pathway ──────────────────────────────────────────────────────
  let treatmentPathway = "";
  if (ivThrombolysisEligibility === "eligible" && thrombectomyEligibility === "eligible") {
    treatmentPathway =
      "DUAL REPERFUSION: Administer IV thrombolysis immediately, then proceed directly to thrombectomy (bridging therapy). Do not delay thrombectomy for thrombolysis response.";
  } else if (ivThrombolysisEligibility === "eligible") {
    treatmentPathway =
      "IV THROMBOLYSIS: Administer tenecteplase 0.25 mg/kg (preferred) or alteplase 0.9 mg/kg. Admit to stroke unit. Monitor BP, neuro exam q15min × 2h, then q30min × 6h.";
  } else if (thrombectomyEligibility === "eligible" || thrombectomyEligibility === "consider_extended_window") {
    treatmentPathway =
      "MECHANICAL THROMBECTOMY: Activate neurointerventional team immediately. Target door-to-puncture <60 min. Stent retriever or aspiration catheter per operator preference.";
  } else {
    treatmentPathway =
      "MEDICAL MANAGEMENT: Aspirin 325 mg loading dose (if no thrombolysis). Admit to stroke unit. BP management, glycemic control, dysphagia screening, early mobilization.";
  }

  // ─── Next Steps ─────────────────────────────────────────────────────────────
  nextSteps.push("Activate stroke code — time is brain (1.9 million neurons lost per minute without reperfusion)");
  nextSteps.push("Obtain STAT CT head (non-contrast) + CT angiography head/neck");
  if (
    (input.onsetWindow === "4_5_to_9h" || input.onsetWindow === "wake_up_unknown") &&
    ivThrombolysisEligibility !== "ineligible"
  ) {
    nextSteps.push("CT perfusion or MRI DWI/PWI required for extended window eligibility assessment");
  }
  nextSteps.push("Continuous cardiac monitoring for 24-48h — detect AF (paroxysmal AF in 10-15% of cryptogenic stroke)");
  nextSteps.push("Dysphagia screening before oral intake");
  nextSteps.push("Early neurology consultation and stroke unit admission");

  // ─── Monitoring Plan ────────────────────────────────────────────────────────
  monitoringPlan.push("Neurological exam q1h × 24h post-thrombolysis; q4h thereafter");
  monitoringPlan.push("BP target: <180/105 mmHg for 24h post-thrombolysis; <140/90 mmHg after 24h");
  monitoringPlan.push("Glucose target: 140-180 mg/dL (avoid hypoglycemia <80 mg/dL)");
  monitoringPlan.push("Repeat CT/MRI at 24-36h to assess hemorrhagic transformation");
  monitoringPlan.push("Cardiac monitoring × 72h minimum; extended monitoring (30-day) for cryptogenic stroke");

  const evidenceLevel =
    "Class I (AHA/ASA 2026) for IV thrombolysis within 4.5h and thrombectomy for LVO within 6h; Class I for basilar thrombectomy (BASICS, ATTENTION trials)";

  const rationale =
    "The AHA/ASA 2026 guideline expands reperfusion windows based on perfusion imaging (DAWN, DEFUSE-3 for anterior circulation; BASICS, ATTENTION for posterior circulation). " +
    "Tenecteplase is now preferred over alteplase for LVO due to logistical advantages. " +
    "Anticoagulation timing in AF-related stroke follows a severity-based approach (48h for mild, 5-7d for moderate, 14d for severe).";

  return {
    primaryRecommendation:
      thrombectomyEligibility === "eligible"
        ? "Mechanical Thrombectomy — activate neurointerventional team immediately"
        : ivThrombolysisEligibility === "eligible"
        ? "IV Thrombolysis — administer tenecteplase/alteplase immediately"
        : "Medical Management — stroke unit admission, antiplatelet therapy, risk factor control",
    ivThrombolysisEligibility,
    thrombectomyEligibility,
    ivThrombolysisRationale,
    thrombectomyRationale,
    anticoagulationTiming,
    urgentFlags,
    treatmentPathway,
    nextSteps,
    monitoringPlan,
    evidenceLevel,
    rationale,
    references: [
      {
        citation:
          "Prabhakaran S, et al. 2026 Guideline for the Early Management of Patients with Acute Ischemic Stroke. Stroke. 2026.",
        pmid: "AHA/ASA 2026",
      },
      {
        citation:
          "Nogueira RG, et al. Thrombectomy 6 to 24 Hours after Stroke with a Mismatch between Deficit and Infarct (DAWN). N Engl J Med. 2018;378(1):11-21.",
        pmid: "29129157",
      },
      {
        citation:
          "Albers GW, et al. Thrombectomy for Stroke at 6 to 16 Hours with Selection by Perfusion Imaging (DEFUSE-3). N Engl J Med. 2018;378(8):708-718.",
        pmid: "29364767",
      },
      {
        citation:
          "The NINDS rt-PA Stroke Study Group. Tissue plasminogen activator for acute ischemic stroke. N Engl J Med. 1995;333(24):1581-1587.",
        pmid: "7477192",
      },
      {
        citation:
          "Zi W, et al. Effect of Endovascular Treatment Alone vs Intravenous Alteplase Plus Endovascular Treatment on Functional Outcome in Patients With Acute Ischemic Stroke (DEVT). JAMA. 2021;325(3):234-243.",
        pmid: "33464336",
      },
    ],
  };
}

// ─── Helper Functions ──────────────────────────────────────────────────────────

export function getStrokeUrgencyColor(rec: StrokeRecommendation): string {
  if (rec.urgentFlags.length > 0 || rec.thrombectomyEligibility === "eligible") return "red";
  if (rec.ivThrombolysisEligibility === "eligible") return "amber";
  return "blue";
}

export function getStrokeUrgencyLabel(rec: StrokeRecommendation): string {
  if (rec.thrombectomyEligibility === "eligible") return "Activate Stroke Code — Thrombectomy";
  if (rec.ivThrombolysisEligibility === "eligible") return "Administer Thrombolysis Now";
  return "Medical Management";
}
